from __future__ import annotations

from pathlib import Path
from typing import Any, Optional

import polars as pl

from sglang.srt.debug_utils.dump_loader import ValueWithMeta


def _render_polars_as_text(df: pl.DataFrame, *, title: Optional[str] = None) -> str:
    """Render a Polars DataFrame as a simple text table, optionally with a title."""
    lines: list[str] = []
    if title is not None:
        lines.append(title)

    columns: list[str] = df.columns
    lines.append(" | ".join(columns))

    for row in df.iter_rows():
        lines.append(" | ".join("" if v is None else str(v) for v in row))

    return "\n".join(lines)


def _extract_parallel_info(row_data: dict[str, Any], info: dict[str, Any]) -> None:
    """Write parallel dimension entries from ``info`` into ``row_data`` in-place.

    For each ``<base>_rank`` key with a matching ``<base>_size`` key, sets
    ``row_data[base] = "{rank}/{size}"``. No-op when ``info`` is empty or reports
    an error; keys without a matching ``_size`` are skipped.
    """
    if not info or "error" in info:
        return

    for key in info:
        if not key.endswith("_rank"):
            continue
        base: str = key[: -len("_rank")]
        size_key: str = f"{base}_size"
        if size_key not in info:
            continue
        row_data[base] = f"{info[key]}/{info[size_key]}"


def _load_meta(dump_dir: Path, filename: str) -> dict[str, Any]:
    return ValueWithMeta.load(Path(dump_dir) / filename).meta


def _to_token_list(value: Any) -> list[int]:
    if hasattr(value, "reshape") and hasattr(value, "tolist"):
        return list(value.reshape(-1).tolist())
    if isinstance(value, (list, tuple)):
        return list(value)
    return [value]


def _collect_rank_info(
    df: pl.DataFrame, dump_dir: Path
) -> Optional[list[dict[str, Any]]]:
    """Collect deduplicated per-rank parallel topology info from dump files."""
    rows = df.filter(pl.col("name") == "input_ids")
    if rows.height == 0:
        return None

    result: list[dict[str, Any]] = []
    seen_ranks: set[Any] = set()
    for row in rows.iter_rows(named=True):
        rank = row.get("rank")
        if rank in seen_ranks:
            continue
        seen_ranks.add(rank)

        entry: dict[str, Any] = {"rank": rank}
        meta = _load_meta(dump_dir, row["filename"])
        info = meta.get("sglang_parallel_info") or {}
        _extract_parallel_info(entry, info)
        result.append(entry)

    return result


def _collect_input_ids_and_positions(
    df: pl.DataFrame, dump_dir: Path, *, tokenizer: Any = None
) -> Optional[list[dict[str, Any]]]:
    """Collect input token ids and positions per (step, rank) from dump files."""
    rows = df.filter(pl.col("name").is_in(["input_ids", "positions"]))
    if rows.height == 0:
        return None

    grouped: dict[tuple[Any, Any], dict[str, str]] = {}
    for row in rows.iter_rows(named=True):
        key = (row.get("step"), row.get("rank"))
        grouped.setdefault(key, {})[row["name"]] = row["filename"]

    result: list[dict[str, Any]] = []
    for step, rank in sorted(grouped, key=lambda k: (k[0], k[1])):
