        positions_list: Optional[list[int]] = None
        if "positions" in files:
            positions_list = _to_token_list(
                _load_meta_value(dump_dir, files["positions"])
            )

        if ids_list is not None:
            num_tokens = len(ids_list)
        elif positions_list is not None:
            num_tokens = len(positions_list)
        else:
            num_tokens = 0

        entry: dict[str, Any] = {
            "step": step,
            "rank": rank,
            "num_tokens": num_tokens,
            "input_ids": str(ids_list) if ids_list is not None else str([]),
            "positions": str(positions_list) if positions_list is not None else str([]),
        }

        if tokenizer is not None:
            entry["decoded_text"] = repr(
                tokenizer.decode(ids_list or [], skip_special_tokens=False)
            )

        result.append(entry)

    return result


def _load_meta_value(dump_dir: Path, filename: str) -> Any:
    return ValueWithMeta.load(Path(dump_dir) / filename).value
